import React from "react";
import { Link, useNavigate } from "react-router-dom";
import { ShoppingBag, User, LogOut } from "lucide-react";
import { useCart } from "../context/CartContext";
import { useAuth } from "../context/AuthContext";

export default function Header({ onCartClick }) {
  const { count } = useCart();
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  return (
    <header
      style={{
        position: "sticky",
        top: 0,
        zIndex: 40,
        background: "var(--night)",
        borderBottom: "1px solid var(--border-dark)",
      }}
    >
      <div className="container" style={{ padding: "14px 24px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <Link to="/" className="focus-ring" style={{ display: "flex", alignItems: "center", gap: 9 }}>
          <span
            style={{
              width: 34,
              height: 34,
              borderRadius: 10,
              background: "var(--chili)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <TiffinMark />
          </span>
          <span className="disp" style={{ fontSize: 20, fontWeight: 700, color: "#FBF1E1", letterSpacing: "-0.01em" }}>
            Healthy Food
          </span>
        </Link>

        <nav style={{ display: "flex", gap: 4, alignItems: "center" }}>
          <NavLink to="/menu">Menu</NavLink>
          <NavLink to="/orders">Track Order</NavLink>

          {user ? (
            <button
              onClick={() => {
                logout();
                navigate("/");
              }}
              className="focus-ring"
              title="Log out"
              style={{
                marginLeft: 8,
                display: "flex",
                alignItems: "center",
                gap: 6,
                padding: "8px 14px",
                borderRadius: 999,
                border: "1px solid var(--border-dark)",
                background: "var(--night-2)",
                fontSize: 13.5,
                fontWeight: 700,
                color: "#FBF1E1",
              }}
            >
              <User size={15} /> {user.name.split(" ")[0]} <LogOut size={13} />
            </button>
          ) : (
            <NavLink to="/login">Log in</NavLink>
          )}

          <button
            onClick={onCartClick}
            className="focus-ring"
            style={{
              position: "relative",
              marginLeft: 8,
              width: 40,
              height: 40,
              borderRadius: "50%",
              border: "1px solid var(--border-dark)",
              background: "var(--night-2)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <ShoppingBag size={18} color="var(--marigold)" />
            {count > 0 && (
              <span
                style={{
                  position: "absolute",
                  top: -4,
                  right: -4,
                  background: "var(--chili)",
                  color: "#FFFCF6",
                  fontSize: 11,
                  fontWeight: 800,
                  borderRadius: 999,
                  minWidth: 18,
                  height: 18,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  padding: "0 4px",
                }}
              >
                {count}
              </span>
            )}
          </button>
        </nav>
      </div>
    </header>
  );
}

function TiffinMark() {
  return (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
      <path d="M8 5 Q12 1 16 5" stroke="#FBF1E1" strokeWidth="2" strokeLinecap="round" />
      <rect x="6" y="4.5" width="12" height="2.4" rx="1.2" fill="#FBF1E1" />
      <rect x="5" y="7.2" width="14" height="5.4" rx="1.4" fill="#FBF1E1" />
      <rect x="5" y="13" width="14" height="5.4" rx="1.4" fill="#FBF1E1" opacity="0.75" />
      <rect x="4.3" y="12.2" width="15.4" height="1.6" rx="0.8" fill="var(--chili)" />
    </svg>
  );
}

function NavLink({ to, children }) {
  return (
    <Link
      to={to}
      className="focus-ring"
      style={{
        padding: "8px 14px",
        borderRadius: 999,
        fontSize: 14,
        fontWeight: 600,
        color: "#D8C9B5",
      }}
    >
      {children}
    </Link>
  );
}
